import numpy as np
from rdkit import Chem
from rdkit.Chem import AllChem
from rdkit.Geometry import Point3D
rw=Chem.RWMol(); names={}
def atom(el,name,charge=0):
 a=Chem.Atom(el); a.SetFormalCharge(charge); a.SetNoImplicit(True); i=rw.AddAtom(a); names[name]=i; return i
def bond(a,b,t=Chem.BondType.SINGLE): rw.AddBond(a,b,t)
Ns=[atom('N',f'N{i}',[1,0,-1,-1][i]) for i in range(4)]
bond(Ns[0],Ns[1])
rings=[]
for k,(a,b) in enumerate([(0,1),(0,2),(1,3)]):
 ring=[atom('C',f'ar{k}_{j}') for j in range(6)]; rings.append(ring)
 for j in range(6):
  rw.GetAtomWithIdx(ring[j]).SetIsAromatic(True); bond(ring[j],ring[(j+1)%6],Chem.BondType.AROMATIC)
 bond(Ns[a],ring[0]); bond(Ns[b],ring[1])
 # all other aromatic Cs each have one H
 for j in range(2,6): h=atom('H',f'Har{k}_{j}'); bond(ring[j],h)
Ps=[atom('P',f'P{i}') for i in range(3)]
bond(Ns[0],Ps[0])
for k,n in [(1,2),(2,3)]:
 c=atom('C',f'CH2_{k}'); bond(Ns[n],c);bond(c,Ps[k])
 for j in range(2): h=atom('H',f'HCH2_{k}_{j}');bond(c,h)
for k,p in enumerate(Ps):
 for j in range(2):
  c=atom('C',f'iPr{k}_{j}');bond(p,c);h=atom('H',f'HiPr{k}_{j}');bond(c,h)
  for l in range(2):
   m=atom('C',f'Me{k}_{j}_{l}');bond(c,m)
   for q in range(3):h=atom('H',f'HMe{k}_{j}_{l}_{q}');bond(m,h)
Nn=atom('N','Nprox'); Nt=atom('N','Ndist');bond(Nn,Nt,Chem.BondType.TRIPLE)
m=rw.GetMol();Chem.SanitizeMol(m)
print('Organic atoms',m.GetNumAtoms(),Chem.MolToSmiles(m), 'UFFparams',AllChem.UFFHasAllMoleculeParams(m))
# Initial ring core points
ct=np.array([0.,0.,1.25]);cb=np.array([0.,0.,-1.25])
angles=np.deg2rad([25,-20,127,240]); Npoints=np.c_[1.82*np.cos(angles),1.82*np.sin(angles),[0.75,0.75,1.15,1.15]]
pangles=np.deg2rad([25,127,240]);Ppoints=np.c_[2.12*np.cos(pangles),2.12*np.sin(pangles),np.full(3,-0.85)]
coordmap={}
for i,p in zip(Ns,Npoints):coordmap[i]=Point3D(*p)
for i,p in zip(Ps,Ppoints):coordmap[i]=Point3D(*p)
coordmap[Nn]=Point3D(0,0,-3.10);coordmap[Nt]=Point3D(0,0,-4.22)
p=AllChem.ETKDGv3();p.randomSeed=295;p.useRandomCoords=True;p.SetCoordMap(coordmap);p.maxIterations=3000;p.ignoreSmoothingFailures=True
ret=AllChem.EmbedMolecule(m,p)
print('Embed result',ret)
if ret<0:
 p.SetCoordMap({});ret=AllChem.EmbedMolecule(m,p);print('Unconstrained result',ret)
if ret<0:raise RuntimeError('embedding failed')
# ETKDG coordmap constraints are not absolute guaranteed, overwrite exact core coordinates
conf=m.GetConformer()
for i,pos in coordmap.items():conf.SetAtomPosition(i,pos)
# fix terminal N2 initially since RDKit embeds disconnected fragment near ligand centroid, already overwritten
ff=AllChem.UFFGetMoleculeForceField(m,ignoreInterfragInteractions=False)
itop=ff.AddExtraPoint(*ct,fixed=False)-1
ibot=ff.AddExtraPoint(*cb,fixed=False)-1
print('Extra points',itop,ibot)
def dist(a,b,r,k=200.):ff.AddDistanceConstraint(int(a),int(b),r,r,k)
def angle(a,b,c,v,k=0.4):ff.UFFAddAngleConstraint(int(a),int(b),int(c),False,float(v),float(v),k)
for n in Ns:dist(n,itop,1.95,350.)
for pidx in Ps:dist(pidx,ibot,2.23,350.)
dist(itop,ibot,2.43,400.)
dist(ibot,Nn,1.85,350.);angle(ibot,Nn,Nt,180,5.)
